# frozen_string_literal: true

module Ztlp
  # The gateway install script (PLAN-services-wizard-and-helpdesk.md slice 5): one copy-paste block a
  # person runs as root on the gateway's box. It writes the shape every production gateway runs
  # (compose, host networking, uid 1000, /data with a persistent QUIC cert, ZTLP_HMAC_SECRET_<ZONE>
  # from .env), creates the identity inside the image only when there is none, and starts it.
  #
  # Every generated file goes through a QUOTED heredoc (no shell expansion). Secrets appear only in
  # the .env block (mode 600). Any value with a newline/control character is refused (Unsafe) so a
  # value can never end a heredoc early and run commands.
  class GatewayInstall
    class Unsafe < StandardError; end

    QUIC_CERT_DIR = "/data/quic-cert"
    SECRET = /\A[!-~]{8,512}\z/ # printable ASCII, no spaces, no newlines

    def self.slug(gateway) = "#{gateway.name}-#{gateway.zone.name.tr('.', '-')}"
    def self.dir(gateway) = "/opt/ztlp-gateway-#{slug(gateway)}"
    def self.container(gateway) = "ztlp-gateway-#{slug(gateway)}"
    def self.relay_env(gateway) = ServiceRegistrar.relay_env_var(gateway.zone)

    # What stops a complete script from being rendered (empty = ready).
    def self.missing(gateway)
      list = []
      list << "only rust_listen gateways can be installed from the panel" unless gateway.kind == "rust_listen"
      list << "the #{gateway.zone.name} relay secret is not set in the panel" if gateway.zone.relay_secret_ct.blank?
      services = gateway.services.where(enabled: true).order(:name).to_a
      list << "the gateway has no enabled service" if services.empty?
      services.each { |s| list << "service #{s.name} has no backend" if s.backend.blank? }
      list
    end

    def self.script(gateway, relay_secret:, header_secret:)
      check_secret!(relay_secret, "relay secret")
      check_secret!(header_secret, "header secret") if gateway.inject_headers
      env = [ "#{relay_env(gateway)}=#{relay_secret}" ]
      env << "GATEWAY_HEADER_SECRET=#{header_secret}" if gateway.inject_headers
      image = safe!(gateway.effective_image)
      fqdn = gateway.ns_name

      <<~SH
        #!/usr/bin/env bash
        # ZTLP gateway install: #{fqdn}
        # Generated by the ZTLP admin panel at #{Time.current.utc.iso8601}. Run it as root on: #{safe!(gateway.host_note.presence || 'the gateway box')}
        # It contains secrets: run it, then do not keep a copy anywhere else.
        set -euo pipefail

        DIR=#{dir(gateway)}
        IMAGE=#{image}

        command -v docker >/dev/null || { echo "docker is not installed on this box" >&2; exit 1; }
        docker compose version >/dev/null 2>&1 || { echo "docker compose v2 is not installed on this box" >&2; exit 1; }
        docker image inspect "$IMAGE" >/dev/null 2>&1 || docker pull "$IMAGE" || { echo "image $IMAGE is not available: load it on this box first (docker load < image.tar)" >&2; exit 1; }

        mkdir -p "$DIR/data"
        cd "$DIR"
        umask 077

        cat > .env <<'ZTLP_ENV'
        #{env.join("\n")}
        ZTLP_ENV
        chmod 600 .env

        cat > docker-compose.yml <<'ZTLP_COMPOSE'
        #{compose(gateway).chomp}
        ZTLP_COMPOSE

        cat > data/policy.toml <<'ZTLP_POLICY'
        #{policy(gateway).chomp}
        ZTLP_POLICY

        [ -s data/identity.json ] || docker run --rm --user 0:0 -v "$DIR/data:/data" --entrypoint ztlp "$IMAGE" keygen --output /data/identity.json
        chown -R 1000:1000 data

        docker compose up -d
        sleep 8
        docker compose logs --tail 40 | grep -E "QUIC cert|registered|listening|rror" || true
        echo
        echo "Installed in $DIR. In the panel, press 'Check now' on #{fqdn}: it turns online once the gateway is on the name server."
      SH
    end

    # No secrets: values come from .env through compose interpolation.
    def self.compose(gateway)
      relay = gateway.effective_relay
      cmd = [ "listen", "--gateway", "--bind", "0.0.0.0:#{gateway.bind_port}", "--key", "/data/identity.json" ]
      gateway.services.where(enabled: true).order(:name).each do |s|
        cmd += [ "--forward", "#{s.name}:#{s.backend.to_s.sub(%r{\Ahttps?://}, '')}" ]
      end
      cmd += [ "--ns-server", gateway.effective_ns_server ]
      cmd += [ "--relay", relay ] if relay.present?
      cmd += [ "--service-name", gateway.name, "--zone", gateway.zone.name, "--ns-register-name", gateway.ns_name,
               "--max-sessions", gateway.max_sessions.to_s, "--policy", "/data/policy.toml" ]
      cmd << "--no-punch" unless gateway.punch
      cmd += [ "--http-inject-headers", "--header-hmac-secret", "${GATEWAY_HEADER_SECRET}" ] if gateway.inject_headers
      Array(gateway.subject_map).each { |line| cmd += [ "--admin-pubkey-email", line ] }

      lines = cmd.map { |arg| "      - #{yaml_scalar(safe!(arg))}" }
      <<~YAML
        # ZTLP gateway #{gateway.ns_name} (generated by the ZTLP admin panel). Secrets live in .env.
        services:
          ztlp-gateway:
            image: #{safe!(gateway.effective_image)}
            container_name: #{container(gateway)}
            restart: unless-stopped
            network_mode: host
            user: "1000:1000"
            environment:
              ZTLP_QUIC_CERT_DIR: #{QUIC_CERT_DIR}
              #{relay_env(gateway)}: "${#{relay_env(gateway)}}"
              RUST_LOG: info
            volumes:
              - ./data:/data
            entrypoint: ["ztlp"]
            command:
        #{lines.join("\n")}
      YAML
    end

    def self.policy(gateway) = PolicyRenderer.render(gateway).each_line.map { |l| safe!(l.chomp) }.join("\n") + "\n"

    # After a rule change: rewrite the policy file and restart the gateway (keeps its identity and
    # QUIC cert, so client pins stay valid). No secrets.
    def self.policy_update_script(gateway)
      <<~SH
        #!/usr/bin/env bash
        # Update the access policy of gateway #{gateway.ns_name} (no secrets in this block)
        set -euo pipefail
        cd #{dir(gateway)}
        cat > data/policy.toml <<'ZTLP_POLICY'
        #{policy(gateway).chomp}
        ZTLP_POLICY
        chown 1000:1000 data/policy.toml
        docker compose restart
      SH
    end

    # What the app behind the gateway needs to verify the signed X-ZTLP-* headers.
    def self.app_env(gateway, header_secret:)
      "ZTLP_GATEWAY_HEADER_SECRET=#{header_secret}\nZTLP_GATEWAY_AUDIENCE=#{gateway.name}\n"
    end

    class << self
      private

      def check_secret!(value, what)
        raise Unsafe, "#{what} must be 8-512 printable characters with no spaces" unless value.to_s.match?(SECRET)
      end

      # No newline or control character can reach a heredoc body.
      def safe!(value)
        s = value.to_s
        raise Unsafe, "value contains a control character: #{s.inspect[0, 40]}" if s.match?(/[\x00-\x1f\x7f]/)

        s
      end

      # Quote args YAML would otherwise read as numbers/booleans or that contain special characters.
      def yaml_scalar(arg)
        return arg if arg.match?(%r{\A--?[a-z][a-z0-9-]*\z}) || arg.match?(%r{\A[a-z][a-z0-9.-]*\z}) ||
                      arg.match?(%r{\A/[A-Za-z0-9._/-]+\z}) || arg.match?(/\A[A-Za-z0-9.-]+:[A-Za-z0-9.:-]+\z/)

        "\"#{arg.gsub('\\', '\\\\\\\\').gsub('"', '\\"')}\""
      end
    end
  end
end
